#define TMAP_COUNT (sizeof(tmap_entries) / sizeof(tmap_entries[0]))

const uint8_t *embedded_tilemap(const char *path, size_t *out_size) {
    for (size_t i = 0; i < TMAP_COUNT; i++) {
        if (strcmp(path, tmap_entries[i].path) == 0) {
            *out_size = tmap_entries[i].size;
            return tmap_entries[i].data;
        }
    }
    *out_size = 0;
    return NULL;
}
